// Oracle helpers. Generated by the framework; read-only to agents.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

// Held-out runs point this at a private copy of the fixtures.
const DIR = process.env.CHESS_FIXTURES_DIR ?? join(import.meta.dirname, "fixtures");

export function fixture<T = any>(name: string): T[] {
  const path = join(DIR, `${name}.json`);
  return existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : [];
}

// Areas load lazily inside each test, so a missing area fails test by test, not the whole run.
// The path is built at run time on purpose: a literal path is resolved when the file is
// transformed, and one missing area would then fail every test in the file.
const area = (name: string): Promise<any> => import(/* @vite-ignore */ `../src/${name}/index.ts`);
export const core = () => area("core");
export const notation = () => area("notation");
export const engine = () => area("engine");
export const clock = () => area("clock");
export const sound = () => area("sound");
export const ui = () => area("ui");

export const sorted = (xs: string[]) => [...xs].sort();
